Value.Calculation:
epSQLExecute (
	"UPDATE Nivelacija SET" &
	"  UkupnoStaraVrijednost = ?," &
	"  UkupnoNovaVrijednost = ?," &
	"  UkupnoRazlika = ?," &
	"  UkupnoStaraVrijednostBezPDV = ?," &
	"  UkupnoNovaVrijednostBezPDV = ?," &
	"  UkupnoRazlikaRUC = ?," &
	"  UkupnoRazlikaPDV = ?" &
	" WHERE PrimaryKey = ?" ;
	"" ;
	$staraBruto ; $novaBruto ; $razlika ;
	$staraNeto ; $novaNeto ; $razlikaRUC ; $razlikaPDV ;
	$nivelacijaId
)

Response_SetData ( JSONSetElement ( "{}" ;
	[ "brojStavki" ; $cnt ; JSONNumber ] ;
	[ "ukupnoStaraVrijednost" ; $staraBruto ; JSONNumber ] ;
	[ "ukupnoNovaVrijednost" ; $novaBruto ; JSONNumber ] ;
	[ "ukupnoRazlika" ; $razlika ; JSONNumber ] ;
	[ "ukupnoStaraVrijednostBezPDV" ; $staraNeto ; JSONNumber ] ;
	[ "ukupnoNovaVrijednostBezPDV" ; $novaNeto ; JSONNumber ] ;
	[ "ukupnoRazlikaRUC" ; $razlikaRUC ; JSONNumber ] ;
	[ "ukupnoRazlikaPDV" ; $razlikaPDV ; JSONNumber ]
) )
